#include <iostream>
#include <vector>
#include <cassert>
using namespace std;

struct Mat {
    int rows, cols;
    vector<long long> data;
    Mat(int r=0,int c=0):rows(r),cols(c),data(r*c){}
    long long& at(int r,int c){return data[r*cols+c];}
    long long at(int r,int c)const{return data[r*cols+c];}
    Mat& add(const Mat& m){
        assert(rows==m.rows && cols==m.cols);
        for(int i=0;i<rows*cols;++i)data[i]+=m.data[i];
        return *this;
    }
    Mat& subtract(const Mat& m){
        assert(rows==m.rows && cols==m.cols);
        for(int i=0;i<rows*cols;++i)data[i]-=m.data[i];
        return *this;
    }
    Mat& multiply(const Mat& m){
        assert(cols==m.rows);
        Mat res(rows,m.cols);
        for(int i=0;i<rows;++i){
            for(int j=0;j<m.cols;++j){
                for(int k=0;k<cols;++k){
                    res.at(i,j)+=at(i,k)*m.at(k,j)%mod;
                }
                res.at(i,j)%=mod;
            }
        }
        *this=res;
        return *this;
    }
    static Mat identity(int n){
        Mat res(n,n);
        for(int i=0;i<n;++i)res.at(i,i)=1;
        return res;
    }
    static Mat power(Mat a,int n){
        assert(a.rows==a.cols);
        Mat res=identity(a.rows);
        while(n){
            if(n&1)res.multiply(a);
            a.multiply(a);
            n>>=1;
        }
        return res;
    }
};

vector<Mat> A(65);
long long calc(int i,int k){
    return Mat::power(A[i+k],k-i)*Mat::power(A[i],i);
}

long long solve(long long n,long long k){
    long long cnt=0,tmp=n;
    while(tmp){tmp/=k;++cnt;}
    vector<Mat> b(cnt+5),c(cnt+5),d(k+1);
    b[0]=A[k-1];
    c[0]=Mat::power(b[0],k-1);
    b[1]=calc(k-1,k);
    c[1]=Mat::power(b[1],k-1);
    Mat s=Mat::identity(2*k+1);
    for(int j=2;j<=cnt+1;++j){
        b[j]=calc(k-j%k,k);
        s*=c[j-1];
        b[j]*=s;
        c[j]=Mat::power(b[j],k-1);
    }
    int idx=1,rem=n%k;
    n-=rem;
    int q=0;
    long long tmp2=n;
    if(tmp2){while(tmp2%k==0){++q;tmp2/=k;}}
    q=(k-q%k)%k;
    Mat ans=Mat::identity(2*k+1);
    ans=Mat::power(A[q],rem)*Mat::power(A[q+k],max(rem-q,0));
    n/=k;
    if(n==0){return (ans.at(2*k,0)+ans.at(0,0))%mod;}
    --n;
    while(n){
        int t=n%k;
        if(t){ans*=Mat::power(b[idx],t);}
        n/=k;++idx;
    }
    ans*=b[1];
    return (ans.at(2*k,0)+ans.at(0,0))%mod;
}

int main(){
    long long n,k;
    cin>>n>>k;
    for(int i=0;i<=2*k;++i){
        A[i]=Mat(2*k+1);
        for(int j=0;j<i;++j)A[i].at(0,j)=1;
        for(int j=0;j<2*k-1;++j)A[i].at(j+1,j)=1;
        A[i].at(2*k,0)=1;
        A[i].at(2*k,2*k)=1;
    }
    cout<<solve(n,k)<<endl;
    return 0;
}
